// Deletes generated Android native build output so the next `npx expo run:android`
// starts clean: the `android/` project (regenerated by `npx expo prebuild`) and every
// library's `android/build` and `android/.cxx` (stale CMake/Gradle caches keep absolute
// paths, so they must go after moving the project folder).
// Stop Gradle first (`cd android && ./gradlew --stop`) if a build ran recently.
import { existsSync, readdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
const targets = [join(root, 'android')];

function packageDirs(nodeModules) {
  if (!existsSync(nodeModules)) return [];
  return readdirSync(nodeModules, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith('.'))
    .flatMap((d) => {
      const dir = join(nodeModules, d.name);
      if (!d.name.startsWith('@')) return [dir];
      return readdirSync(dir, { withFileTypes: true })
        .filter((s) => s.isDirectory())
        .map((s) => join(dir, s.name));
    });
}

for (const pkg of packageDirs(join(root, 'node_modules'))) {
  for (const cache of ['build', '.cxx']) targets.push(join(pkg, 'android', cache));
}

let removed = 0;
for (const target of targets) {
  if (!existsSync(target)) continue;
  rmSync(target, { recursive: true, force: true, maxRetries: 3 });
  console.log(`removed ${target.slice(root.length + 1)}`);
  removed++;
}
console.log(removed ? `Cleared ${removed} Android build cache folder(s).` : 'Nothing to clear.');
